const request = $input.first().json;
const envelope = request.body && typeof request.body === 'object' ? request.body : request;
if (envelope.schema !== 'dominium.toa.technician-locations.v1') throw new Error('Schema GPS inválido');
if (!Array.isArray(envelope.resources)) throw new Error('Lote sem resources');
const safeKey = (value) => String(value || 'sem-id').replace(/[.#$\[\]\/]/g, '_').slice(0, 180);
const hash = (value) => { const text = JSON.stringify(value); let result = 2166136261; for (let index = 0; index < text.length; index += 1) { result ^= text.charCodeAt(index); result = Math.imul(result, 16777619); } return (result >>> 0).toString(16); };
const updates = {};
let accepted = 0;
let visits = 0;
let ignored = 0;
for (const resource of envelope.resources) {
  const technician = resource.technician && typeof resource.technician === 'object' ? resource.technician : {};
  const technicianKey = safeKey(technician.login || technician.id);
  if (technicianKey === 'sem-id') { ignored += 1; continue; }
  const metadata = (base) => { updates[`${base}/technician_id`] = String(technician.id || ''); updates[`${base}/technician_login`] = String(technician.login || ''); updates[`${base}/technician_name`] = String(technician.name || technician.login || technician.id || ''); updates[`${base}/bucket`] = String(resource.bucket || ''); updates[`${base}/profile`] = String(resource.profile || ''); updates[`${base}/updated_at`] = envelope.publishedAt || new Date().toISOString(); };
  for (const point of resource.points || []) {
    const observedAt = String(point.observed_at || ''); const day = observedAt.slice(0, 10); const latitude = Number(point.latitude); const longitude = Number(point.longitude);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !Number.isFinite(latitude) || !Number.isFinite(longitude)) { ignored += 1; continue; }
    const base = `dominium/toa/history/technicianLocations/${day}/technicians/${technicianKey}`; metadata(base); updates[`${base}/last_at`] = observedAt;
    const pointKey = safeKey(`${observedAt}_${hash([latitude, longitude])}`);
    updates[`${base}/points/${pointKey}`] = { observed_at: observedAt, latitude, longitude, accuracy_m: Number.isFinite(Number(point.accuracy_m)) ? Number(point.accuracy_m) : null, speed_kmh: Number.isFinite(Number(point.speed_kmh)) ? Number(point.speed_kmh) : null, heading: Number.isFinite(Number(point.heading)) ? Number(point.heading) : null, altitude_m: Number.isFinite(Number(point.altitude_m)) ? Number(point.altitude_m) : null }; accepted += 1;
  }
  for (const visit of resource.visits || []) {
    const latitude = Number(visit.latitude); const longitude = Number(visit.longitude); const day = String(visit.date || visit.scheduled_at || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !Number.isFinite(latitude) || !Number.isFinite(longitude)) { ignored += 1; continue; }
    const base = `dominium/toa/history/technicianLocations/${day}/technicians/${technicianKey}`; metadata(base);
    const visitKey = safeKey(`${visit.activity_id || 'atividade'}_${latitude.toFixed(6)}_${longitude.toFixed(6)}`);
    updates[`${base}/visits/${visitKey}`] = { date: day, scheduled_at: String(visit.scheduled_at || ''), latitude, longitude, marker_label: String(visit.marker_label || ''), activity_id: String(visit.activity_id || ''), os_number: String(visit.os_number || ''), contract: String(visit.contract || ''), service: String(visit.service || ''), status: String(visit.status || ''), service_window: String(visit.service_window || '') }; visits += 1;
  }
}
if (!accepted && !visits) throw new Error('Nenhum ponto GPS ou atendimento válido no lote');
return [{ json: { updates, summary: { accepted, visits, ignored, paths: Object.keys(updates).length } } }];
